'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var isFunction = require( '@stdlib/assert/is-function' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var identity = require( '@stdlib/utils/identity-function' );
var isEqual = require( '@stdlib/number/uint64/base/assert/is-equal' );
var add = require( '@stdlib/number/uint64/base/add' );
var BigInt = require( '@stdlib/bigint/ctor' );
var Number = require( '@stdlib/number/ctor' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var Uint64Array = require( './../lib' );


// VARIABLES //

var HAS_BIGINTS = hasBigIntSupport();
var opts = {
	'skip': !HAS_BIGINTS
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Uint64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `map` method', function test( t ) {
	t.strictEqual( hasOwnProp( Uint64Array.prototype, 'map' ), true, 'has property' );
	t.strictEqual( isFunction( Uint64Array.prototype.map ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a 64-bit unsigned integer array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Uint64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.map.call( value, identity );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Uint64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.map( value );
		};
	}
});

tape( 'the method returns an empty array if operating on an empty 64-bit unsigned integer array', function test( t ) {
	var arr;
	var out;

	arr = new Uint64Array();
	out = arr.map( identity );

	t.strictEqual( instanceOf( out, Uint64Array ), true, 'returns expected value' );
	t.strictEqual( out.length, 0, 'returns expected value' );
	t.notEqual( out, arr, 'returns a new instance' );
	t.end();
});

tape( 'the method returns a new 64-bit unsigned integer array containing elements which are the result of a callback function', function test( t ) {
	var expected;
	var actual;
	var arr;
	var i;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = [ 2, 4, 6 ];
	actual = arr.map( scale );

	t.strictEqual( instanceOf( actual, Uint64Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	t.notEqual( actual, arr, 'returns a new instance' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isEqual( actual.get( i ), new Uint64( expected[ i ] ) ), true, 'returns expected value' );
	}
	t.end();

	function scale( v ) {
		return add( v, v );
	}
});

tape( 'the method supports providing an execution context', function test( t ) {
	var expected;
	var actual;
	var arr;
	var ctx;
	var i;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = [ 2, 4, 6 ];
	ctx = {
		'count': 0
	};
	actual = arr.map( scale, ctx );

	t.strictEqual( instanceOf( actual, Uint64Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isEqual( actual.get( i ), new Uint64( expected[ i ] ) ), true, 'returns expected value' );
	}
	t.strictEqual( ctx.count, 3, 'returns expected value' );
	t.end();

	function scale( v ) {
		this.count += 1; // eslint-disable-line no-invalid-this
		return add( v, v );
	}
});

tape( 'the method supports a map function which returns a nonnegative integer', function test( t ) {
	var expected;
	var actual;
	var arr;
	var i;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = [ 2, 4, 6 ];
	actual = arr.map( scale );

	t.strictEqual( instanceOf( actual, Uint64Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isEqual( actual.get( i ), new Uint64( expected[ i ] ) ), true, 'returns expected value' );
	}
	t.end();

	function scale( v ) {
		return Number( v ) * 2;
	}
});

tape( 'the method supports a map function which returns a bigint', opts, function test( t ) {
	var expected;
	var actual;
	var arr;
	var i;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = [ 2, 4, 6 ];
	actual = arr.map( scale );

	t.strictEqual( instanceOf( actual, Uint64Array ), true, 'returns expected value' );
	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isEqual( actual.get( i ), new Uint64( expected[ i ] ) ), true, 'returns expected value' );
	}
	t.end();

	function scale( v ) {
		return BigInt( Number( v ) * 2 );
	}
});

tape( 'the method throws an error if provided a map function which does not return either a 64-bit unsigned integer or a value which can be converted to a 64-bit unsigned integer', function test( t ) {
	var clbks;
	var arr;
	var i;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	clbks = [
		clbk1,
		clbk2,
		clbk3,
		clbk4,
		clbk5
	];
	for ( i = 0; i < clbks.length; i++ ) {
		t.throws( badValue( clbks[i] ), TypeError, 'throws an error when provided callback '+i );
	}
	t.end();

	function badValue( clbk ) {
		return function badValue() {
			return arr.map( clbk );
		};
	}

	function clbk1() {
		return -1;
	}

	function clbk2() {
		return 3.14;
	}

	function clbk3() {
		return '5';
	}

	function clbk4() {
		return {};
	}

	function clbk5() {
		return [];
	}
});
